<script>
import {onMount} from 'svelte';
import Icon from './Icon.svelte';
import StorageGuide from './StorageGuide.svelte';
import {trackSections} from '../../../packages/web-shared/rail.js';
let rail=$state();
onMount(()=>{const index=rail?.querySelector('details');if(index && matchMedia('(max-width:900px)').matches)index.open=false;return rail?trackSections(rail):undefined});
import '../../../packages/web-shared/styles.css';
import mascot from '../../../packages/web-shared/assets/mascot.png';
import logo from '../../../packages/web-shared/assets/logo.png';
import snippets from '../../../docs/onboarding/snippets.json';
const context=(()=>{try{return JSON.parse(document.getElementById('slurp-context')?.textContent||'{}')}catch{return {}}})();
let reveal=$state(false),revealBot=$state(false),copied=$state('');
const backend=context.backend||'https://YOUR_WORKER.workers.dev',project=context.project||'prj_YOUR_PROJECT';
const syncCommands=context.sync_commands||null;
const origin=backend.replace(/\/$/,''),host=origin.replace(/^https?:\/\//,'');
const fill=(s,keys=false)=>s.replaceAll('YOUR_ORIGIN',origin).replaceAll('YOUR_HOST',host).replaceAll('YOUR_INGEST_URL',context.ingest_url||backend+'/v1/events').replaceAll('YOUR_PROJECT_ID',project).replaceAll('YOUR_BACKEND',backend).replaceAll('YOUR_PUBLISHABLE_KEY',keys?(context.publishable_key||'YOUR_PUBLISHABLE_KEY'):(context.publishable_key?'slurp_pk_••••••••':'YOUR_PUBLISHABLE_KEY'));
async function copy(text,id){try{await navigator.clipboard.writeText(text);copied=id;setTimeout(()=>copied='',2000)}catch{copied='Select and copy the code directly.'}}
</script>
{#if context.guide_only}
<main class="standalone-guide"><a class="brand" href="#storage-guide" aria-label="Slurp storage guide"><img src={logo} alt="Slurp" /></a><StorageGuide standalone /></main>
{:else}
<a class="skip" href="#main">Skip to project quickstart</a>
<div class="shell"><aside class="rail" bind:this={rail}><a class="brand" href="#main" aria-label="Slurp setup"><img src={logo} alt="Slurp" /></a><details class="section-index" open><summary>Project quickstart</summary><nav class="setup-nav" aria-label="Setup sections"><a href="#connect"><Icon name="connections"/><span>01 · Connect</span></a><a href="#sync"><Icon name="sync"/><span>02 · Sync</span></a><a href="#agents"><Icon name="agent"/><span>03 · Agent</span></a><a href="#reports"><Icon name="report"/><span>04 · Report</span></a><a href="#hosting"><Icon name="report"/><span>05 · Hosting</span></a></nav></details><p class="rail-note">Your data. Your machine.<br/>This private page is an offline snapshot. Rerun <code>slurp init</code> to refresh it.</p></aside><main id="main" class="content"><section class="hero-split"><div><p class="eyebrow">Your local launchpad</p><h1>Connect your app.<br/><span class="hot">Bring your events home.</span></h1><p class="lede">Connect your app’s events, bring them home, and give your coding agent something real to work with.</p><a class="primary" href="#connect">Connect your app ↗</a></div><img src={mascot} alt="Slurp mascot enjoying a red and blue slushie" /></section><div class="binding"><strong>{context.project?'● Project connected':'● Ready when you are'}</strong><code>{context.project_name||context.project||'No project selected yet'}</code><span>{context.generated_at?'Updated '+new Date(context.generated_at).toLocaleString():'CLI + SDK · Local DuckDB'}</span></div>
<section class="section" id="connect"><div class="heading"><b>01</b><div><h2>Connect your app.</h2><p>Your publishable key sends events. It cannot read them.</p></div></div>{#if context.publishable_key}<div class="install"><code>npm install @hitslop/slurp-sdk</code><button onclick={()=>copy('npm install @hitslop/slurp-sdk','install')}>{copied==='install'?'Copied!':'Copy ↗'}</button></div><p class="small">Publishable keys only send events; they cannot read them. Any language can also send events over HTTP (see the docs).</p><div class="codebox"><div class="codebar"><span>JavaScript / Node</span><div>{#if context.publishable_key}<button onclick={()=>reveal=!reveal}>{reveal?'Hide key':'Reveal key'}</button>{/if}<button onclick={()=>copy(fill(snippets.sdk,true),'code')}>{copied==='code'?'Copied!':'Copy code ↗'}</button></div></div><pre><code>{fill(snippets.sdk,reveal)}</code></pre></div><p class="small">{context.publishable_key?'Copy code includes your publishable key. Reveal it to see the complete snippet.':'Run slurp project setup PROJECT to get your ingest URL and publishable key, then rerun init with those environment values.'}</p><details class="more"><summary>Mobile, or an SDK you already use</summary>{#each [['React Native','reactNative'],['Swift (Segment analytics-swift)','swift'],['HTTP, any language','http'],['Segment (change the host)','segment'],['Sentry (change the DSN)','sentry']] as [label,key]}<div class="codebox"><div class="codebar"><span>{label}</span><div><button onclick={()=>copy(fill(snippets[key],true),key)}>{copied===key?'Copied!':'Copy code ↗'}</button></div></div><pre><code>{fill(snippets[key],reveal)}</code></pre></div>{/each}<p class="small">Segment and Sentry SDKs send to your Worker unchanged; errors land as <code>error</code> events you can query with the <code>errors</code> view. Details in the docs.</p></details>{:else}<p class="note"><strong>This connection is ready for analysis.</strong><br/>Sending new events requires a publishable SDK key from the project owner. Your agent can sync published archives with its read key or your existing login.</p><p class="small">Owners can see the project's publishable keys with <code>slurp project setup {project}</code>, then rerun <code>slurp init</code> with the returned environment values.</p>{/if}</section>
<section class="section" id="sync"><div class="heading"><b>02</b><div><h2>Sync your events.</h2><p>One project, one DuckDB file. Slurp handles offsets and duplicates.</p></div></div>{#if context.database}<div class="storage-location"><span class="eyebrow">{context.workspace_initialized?'Event storage':'Planned event storage'}</span><code>{context.database}</code><p class="small">{context.workspace_initialized?'This project remembers this location. If it is on an external drive, connect the drive before syncing or querying.':'The commands below initialize this location. SQL and report definitions stay in your project.'}</p></div>{/if}<div class="codebox"><div class="codebar"><span>Terminal</span><button onclick={()=>copy(syncCommands||fill(snippets.sync),'sync')}>{copied==='sync'?'Copied!':'Copy commands ↗'}</button></div><pre><code>{syncCommands||fill(snippets.sync)}</code></pre></div><div class="flow">Your app <span>→</span> Slurp archive <span>→</span> Local DuckDB <span>→</span> Your agent</div><p class="note"><strong>New events appear in sync after your Worker next publishes an archive, about every 10 minutes.</strong><br/>With the admin token, <code>slurp sync --now</code> publishes first. Sync never stops on a bad event: <code>slurp health</code> lists anything it set aside. This offline page does not show live status.</p><StorageGuide /></section>
<section class="section" id="agents"><div class="heading"><b>03</b><div><h2>Invite your agent.</h2><p>Codex, Claude, Grok, Muse. Same CLI. Same instructions. Their own read key.</p></div></div><h3>Give a bot access to this project</h3><p>Create a named read-only key, then put it in the bot’s secret store as <code>SLURP_TOKEN</code>. It grants archive reads, not ingestion or project administration.</p><div class="codebox"><div class="codebar"><span>Create a bot key</span><button onclick={()=>copy(fill(snippets.key),'key')}>{copied==='key'?'Copied!':'Copy command ↗'}</button></div><pre><code>{fill(snippets.key)}</code></pre></div>{#if context.read_key}<div class="bot"><strong>Read-only bot key</strong><code>{revealBot?context.read_key:'slurp_sk_••••••••'}</code><button onclick={()=>revealBot=!revealBot}>{revealBot?'Hide':'Reveal'}</button><button onclick={()=>copy(context.read_key,'bot')}>{copied==='bot'?'Copied!':'Copy key'}</button></div>{/if}<div class="codebox agent"><div class="codebar"><span>On the agent’s machine</span><button onclick={()=>copy(fill(snippets.agent),'agent')}>{copied==='agent'?'Copied!':'Copy steps ↗'}</button></div><pre><code>{fill(snippets.agent)}</code></pre></div><div class="codebox agent"><div class="codebar"><span>Or connect an AI client over MCP</span><button onclick={()=>copy(snippets.mcp,'mcp')}>{copied==='mcp'?'Copied!':'Copy ↗'}</button></div><pre><code>{snippets.mcp}</code></pre></div><p class="small">Keys stay out of URLs and skill files. Revoke access with <code>slurp project key revoke</code>. Rerun <code>slurp init</code> to refresh this snapshot.</p></section>
<section class="section" id="reports"><div class="heading"><b>04</b><div><h2>Make a report.</h2><p>Your agent writes SQL and Markdown. Slurp turns them into a report.</p></div></div><blockquote>“Which events changed this week? Save the SQL and make me a report.”</blockquote><div class="install"><code>slurp report build report.md --out ./report --png --pdf</code><button onclick={()=>copy('slurp report build report.md --out ./report --png --pdf','report')}>{copied==='report'?'Copied!':'Copy ↗'}</button></div><p class="small">HTML opens in your browser. PNG and PDF are ready to share. Review the data before sharing.</p></section><section class="section" id="hosting"><div class="heading"><b>05</b><div><h2>Know where it runs.</h2><p>This page stays private and offline. Your events live in your own Cloudflare account.</p></div></div><p>Events are accepted by your Worker, buffered in a Durable Object, then published as compressed archives in your R2 bucket. Usage and cost appear on your Cloudflare bill, not here. Archives stay in R2 until you delete them or set a lifecycle rule.</p><div class="codebox"><div class="codebar"><span>Check your deployment</span></div><pre><code>{snippets.hosting}</code></pre></div><p class="small">Publishable keys can only send events. Keep your admin token and secret keys out of browser code.</p></section><footer><img src={logo} alt="Slurp" /><span>Collect. Sync. Ask something interesting.</span></footer></main></div><div class="toast" role="status" aria-live="polite">{copied==='Select and copy the code directly.'?copied:''}</div>
{/if}
<style>
:global(body:has(.standalone-guide)){background:var(--surface)}
.standalone-guide{max-width:1000px;margin:auto;padding:40px clamp(20px,5vw,64px)}.standalone-guide>.brand{display:inline-block;margin-bottom:12px}
.more{margin:14px 0}.more summary{cursor:pointer;font:600 13px var(--body)}
.hero-split{grid-template-columns:minmax(0,1fr) 150px;margin-bottom:32px}.hero-split h1{font-size:clamp(30px,3vw,40px)}.hero-split .lede{font-size:16px}.binding{display:flex;flex-wrap:wrap;gap:12px 20px;font-size:11px;padding:18px 0;border-top:1px solid var(--rule)}.binding strong{color:#23734f}.binding code{overflow-wrap:anywhere}.binding span{margin-left:auto}.heading{display:flex;gap:16px;margin-bottom:24px}.heading>b{font:600 13px var(--body);color:var(--red);padding-top:7px}.heading p{margin:0}.install{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1px solid var(--rule);border-radius:7px;padding:12px 16px;background:var(--rail)}.install code{overflow-wrap:anywhere}.install button,.bot button{border:0;background:transparent;color:var(--blue);font-size:12px;flex-shrink:0;padding:8px}.small{font-size:12px;margin:12px 0 20px}.storage-location{margin:0 0 20px}.storage-location>code{display:block;overflow-wrap:anywhere;font-size:13px;margin-top:8px}.storage-location .small{margin-bottom:0}.flow{display:flex;flex-wrap:wrap;gap:14px;font-size:13px;margin:24px 0}.flow span{color:var(--red)}.note{font-size:13px}.bot{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.bot code{overflow-wrap:anywhere;max-width:100%}blockquote{margin:24px 0;font-size:20px;line-height:1.5}.toast:not(:empty){position:fixed;bottom:20px;left:20px;right:20px;padding:16px;background:var(--ink);color:white;z-index:50;border-radius:7px}@media(max-width:560px){.hero-split{grid-template-columns:minmax(0,1fr) 80px;display:grid;gap:10px}.hero-split>img{width:80px}.hero-split h1{font-size:28px}.binding span{margin-left:0}}
</style>
